1886	  /**
1887	   * POST /api/plugins/:pluginId/config
1888	   *
1889	   * Save (create or replace) the instance configuration for a plugin.
1890	   *
1891	   * The caller provides the full `configJson` object. The server persists it
1892	   * via `registry.upsertConfig()`.
1893	   *
1894	   * Request body:
1895	   * - `configJson`: Configuration values matching the plugin's `instanceConfigSchema`
1896	   *
1897	   * Response: `PluginConfig`
1898	   * Errors:
1899	   * - 400 if request validation fails
1900	   * - 404 if plugin not found
1901	   */
1902	  router.post("/plugins/:pluginId/config", async (req, res) => {
1903	    assertInstanceAdmin(req);
1904	    const { pluginId } = req.params;
1905	
1906	    const plugin = await resolvePlugin(registry, pluginId);
1907	    if (!plugin) {
1908	      res.status(404).json({ error: "Plugin not found" });
1909	      return;
1910	    }
1911	
1912	    const body = req.body as { configJson?: Record<string, unknown> } | undefined;
1913	    if (!body?.configJson || typeof body.configJson !== "object") {
1914	      res.status(400).json({ error: '"configJson" is required and must be an object' });
1915	      return;
1916	    }
1917	
1918	    // Strip devUiUrl unless the caller is an instance admin. devUiUrl activates
1919	    // a dev-proxy in the static file route that could be abused for SSRF if any
1920	    // board-level user were allowed to set it.
1921	    if (
1922	      "devUiUrl" in body.configJson &&
1923	      !(req.actor.type === "board" && req.actor.isInstanceAdmin)
1924	    ) {
1925	      delete body.configJson.devUiUrl;
1926	    }
1927	
1928	    // Validate configJson against the plugin's instanceConfigSchema (if declared).
1929	    // This ensures CLI/API callers get the same validation the UI performs client-side.
1930	    const schema = plugin.manifestJson?.instanceConfigSchema;
1931	    if (schema && Object.keys(schema).length > 0) {
1932	      const validation = validateInstanceConfig(body.configJson, schema);
1933	      if (!validation.valid) {
1934	        res.status(400).json({
1935	          error: "Configuration does not match the plugin's instanceConfigSchema",
1936	          fieldErrors: validation.errors,
1937	        });
1938	        return;
1939	      }
1940	    }
1941	
1942	    try {
1943	      const result = await registry.upsertConfig(plugin.id, {
1944	        configJson: body.configJson,
1945	      });
1946	      await logPluginMutationActivity(req, "plugin.config.updated", plugin.id, {
1947	        pluginId: plugin.id,
1948	        pluginKey: plugin.pluginKey,
1949	        configKeyCount: Object.keys(body.configJson).length,
1950	      });
1951	
1952	      // Notify the running worker about the config change (PLUGIN_SPEC §25.4.4).
1953	      // If the worker implements onConfigChanged, send the new config via RPC.
1954	      // If it doesn't (METHOD_NOT_IMPLEMENTED), restart the worker so it picks
1955	      // up the new config on re-initialize. If no worker is running, skip.
1956	      if (bridgeDeps?.workerManager.isRunning(plugin.id)) {
1957	        try {
1958	          await bridgeDeps.workerManager.call(
1959	            plugin.id,
1960	            "configChanged",
1961	            { config: body.configJson },
1962	          );
1963	        } catch (rpcErr) {
1964	          if (
1965	            rpcErr instanceof JsonRpcCallError &&
1966	            rpcErr.code === PLUGIN_RPC_ERROR_CODES.METHOD_NOT_IMPLEMENTED
1967	          ) {
1968	            // Worker doesn't handle live config — restart it.
1969	            try {
1970	              await lifecycle.restartWorker(plugin.id);
1971	            } catch {
1972	              // Restart failure is non-fatal for the config save response.
1973	            }
1974	          }
1975	          // Other RPC errors (timeout, unavailable) are non-fatal — config is
1976	          // already persisted and will take effect on next worker restart.
1977	        }
1978	      }
1979	
1980	      res.json(result);
1981	    } catch (err) {
1982	      const message = err instanceof Error ? err.message : String(err);
1983	      res.status(400).json({ error: message });
1984	    }
1985	  });
