2005	   * - 502 if the worker is unavailable
2006	   */
2007	  router.post("/plugins/:pluginId/config/test", async (req, res) => {
2008	    assertBoardOrgAccess(req);
2009	
2010	    if (!bridgeDeps) {
2011	      res.status(501).json({ error: "Plugin bridge is not enabled" });
2012	      return;
2013	    }
2014	
2015	    const { pluginId } = req.params;
2016	
2017	    const plugin = await resolvePlugin(registry, pluginId);
2018	    if (!plugin) {
2019	      res.status(404).json({ error: "Plugin not found" });
2020	      return;
2021	    }
2022	
2023	    if (plugin.status !== "ready") {
2024	      res.status(400).json({
2025	        error: `Plugin is not ready (current status: ${plugin.status})`,
2026	      });
2027	      return;
2028	    }
2029	
2030	    const body = req.body as { configJson?: Record<string, unknown> } | undefined;
2031	    if (!body?.configJson || typeof body.configJson !== "object") {
2032	      res.status(400).json({ error: '"configJson" is required and must be an object' });
2033	      return;
2034	    }
2035	
2036	    // Fast schema-level rejection before hitting the worker RPC.
2037	    const schema = plugin.manifestJson?.instanceConfigSchema;
2038	    if (schema && Object.keys(schema).length > 0) {
2039	      const validation = validateInstanceConfig(body.configJson, schema);
2040	      if (!validation.valid) {
2041	        res.status(400).json({
2042	          error: "Configuration does not match the plugin's instanceConfigSchema",
2043	          fieldErrors: validation.errors,
2044	        });
2045	        return;
2046	      }
2047	    }
2048	
2049	    try {
2050	      const result = await bridgeDeps.workerManager.call(
2051	        plugin.id,
2052	        "validateConfig",
2053	        { config: body.configJson },
2054	      );
2055	
2056	      // The worker returns PluginConfigValidationResult { ok, warnings?, errors? }
2057	      // Map to the frontend-expected shape { valid, message? }
2058	      if (result.ok) {
2059	        const warningText = result.warnings?.length
2060	          ? `Warnings: ${result.warnings.join("; ")}`
2061	          : undefined;
2062	        res.json({ valid: true, message: warningText });
2063	      } else {
2064	        const errorText = result.errors?.length
2065	          ? result.errors.join("; ")
2066	          : "Configuration validation failed.";
2067	        res.json({ valid: false, message: errorText });
2068	      }
2069	    } catch (err) {
2070	      // If the worker does not implement validateConfig, return a structured response
2071	      if (
2072	        err instanceof JsonRpcCallError &&
2073	        err.code === PLUGIN_RPC_ERROR_CODES.METHOD_NOT_IMPLEMENTED
2074	      ) {
2075	        res.json({
2076	          valid: false,
2077	          supported: false,
2078	          message: "This plugin does not support configuration testing.",
2079	        });
2080	        return;
2081	      }
2082	
2083	      // Worker unavailable or other RPC errors
2084	      const bridgeError = mapRpcErrorToBridgeError(err);
2085	      res.status(502).json(bridgeError);
2086	    }
2087	  });
